import type { GuidanceVerification } from '../../types/guidance-verifier';
import { executeContextVerification } from './contextVerification';
import {
  ensureHub,
  requestHub,
  LibraryRequestError,
  libraryErrorDetails,
} from '../../library/HubClient';
import { GuidanceError } from '../../types/guidance';
import { currentLibraryRoot } from '../../services/ProjectLibrary';
import { getConfigManager } from '../../services/ConfigManager';
import { requestServer } from '../client';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import {
  attachOrUnavailable,
  isAttached,
  serverErrorResult,
  transportErrorResult,
} from './shared';
import { contextRequest } from './contextRequest';

export const handleContext = async (
  args: string[],
  options: { signal?: AbortSignal } = {},
): Promise<CliCommandResult> => {
  const accountId = getConfigManager().getUserId();
  const request = await contextRequest(args);
  if ('envelope' in request) return request;
  const { command, endpoint, method, body, projectPath } = request;
  if (!getConfigManager().isAuthenticated() || !accountId) {
    return errorResult(
      command,
      'AUTH_REQUIRED',
      'Sign in to Rivet before using saved context',
    );
  }
  const assertAccount = (): void => {
    if (getConfigManager().getUserId() !== accountId) {
      throw new GuidanceError(
        'guidance_account_changed',
        'Rivet account changed during the context command. Retry with the intended account.',
      );
    }
  };
  try {
    assertAccount();
    if (request.isProjectRequest) {
      const attached = await attachOrUnavailable(command, projectPath);
      if (!isAttached(attached)) return attached;
      assertAccount();
      const response = await requestServer(
        attached,
        `${endpoint}?accountId=${encodeURIComponent(accountId)}`,
      );
      assertAccount();
      return response.status === 200
        ? okResult(command, response.body)
        : serverErrorResult(command, response.status, response.body);
    }
    const hub = await ensureHub({ root: currentLibraryRoot() });
    assertAccount();
    const result = await requestHub({
      hub,
      endpoint,
      method,
      body,
      expectedAccountId: accountId,
    });
    assertAccount();
    if (request.verificationTarget !== undefined) {
      return executeContextVerification({
        command,
        packet: result as GuidanceVerification,
        target: request.verificationTarget,
        projectPath,
        accountId,
        signal: options.signal,
        outputDirectory: request.outputDirectory,
      });
    }
    return okResult(command, result);
  } catch (error) {
    if (error instanceof GuidanceError)
      return errorResult(command, 'OPERATION_FAILED', error.message);
    if (error instanceof LibraryRequestError) {
      let code: 'USAGE_ERROR' | 'AUTH_REQUIRED' | 'OPERATION_FAILED' =
        'OPERATION_FAILED';
      if (error.status === 400) code = 'USAGE_ERROR';
      if (error.status === 401) code = 'AUTH_REQUIRED';
      return errorResult(
        command,
        code,
        error.message,
        libraryErrorDetails(error),
      );
    }
    return transportErrorResult(command, error);
  }
};
